    "stem": "A 64-year-old man is admitted to the inpatient acute medical ward of Royal Adelaide Hospital with clinical findings indicative of Pneumocystis Jirovecii Pneumonia in Immunosuppressed Host. Clinical examination and investigative review confirm high-dose intravenous trimethoprim-sulfamethoxazole and adjuvant corticosteroids. Vitals reveal blood pressure of 124/84 mm Hg, heart rate of 82/min, respiratory rate of 18/min, and temperature of 38.0C (98.5F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of pneumocystis jirovecii pneumonia in immunosuppressed host. Which of the following is the most appropriate next step in clinical management according to Australian Therapeutic Guidelines (eTG) and national consensus guidelines?",
