    "stem": "A 29-year-old man undergoes specialist clinical evaluation at Sir Charles Gairdner Hospital Perth with clinical findings indicative of Miliary Tuberculosis with Acute Diffuse Pulmonary Infiltrates. Clinical examination and investigative review confirm four-drug anti-tubercular therapy with rifampicin, isoniazid, pyrazinamide, and ethambutol. Vitals reveal blood pressure of 132/76 mm Hg, heart rate of 90/min, respiratory rate of 18/min, and temperature of 37.0C (98.4F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of miliary tuberculosis with acute diffuse pulmonary infiltrates. Which of the following is the most appropriate next step in clinical management according to Australian Therapeutic Guidelines (eTG) and national consensus guidelines?",
    "options": [
      {
        "text": "High-dose oral corticosteroid monotherapy without source control",
        "correct": false,
        "explanation": "Incorrect: Systemic corticosteroids without addressing the underlying infectious or structural etiology fail to alter disease progression."
      },
      {
        "text": "Intravenous loop diuretic administration in a hypovolemic or hypotensive patient",
        "correct": false,
        "explanation": "Incorrect: Administering potent loop diuretics during hypoperfusion exacerbates circulatory collapse and accelerates ischemic tubular injury."
      },
      {
        "text": "High-flow oxygen therapy via non-rebreather mask in acute hypercapnic respiratory failure",
        "correct": false,
        "explanation": "Incorrect: Uncontrolled high FiO2 in hypercapnic chronic lung disease abolishes hypoxic respiratory drive, precipitating carbon dioxide narcosis."
      },
      {
        "text": "Four-drug anti-tubercular therapy with rifampicin, isoniazid, pyrazinamide, and ethambutol",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is four-drug anti-tubercular therapy with rifampicin, isoniazid, pyrazinamide, and ethambutol. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Intravenous sodium bicarbonate bolus in mild compensated ketoacidosis",
        "correct": false,
        "explanation": "Incorrect: Alkalinization in mild acidemia paradoxically causes paradoxical CSF acidosis, hypokalemia, and delayed ketone clearance."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Miliary Tuberculosis with Acute Diffuse Pulmonary Infiltrates.\\n\\nClinical Discussion: This clinical presentation corresponds to Miliary Tuberculosis with Acute Diffuse Pulmonary Infiltrates. The cornerstone of management involves four-drug anti-tubercular therapy with rifampicin, isoniazid, pyrazinamide, and ethambutol. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
