    "stem": "A 29-year-old man is evaluated in the emergency receiving department of Royal Prince Alfred Hospital Sydney with clinical findings indicative of Waldenstr\u00f6m Macroglobulinemia with Symptomatic Hyperviscosity. Clinical examination and investigative review confirm emergency therapeutic plasmapheresis followed by clone-directed chemoimmunotherapy. Vitals reveal blood pressure of 127/83 mm Hg, heart rate of 77/min, respiratory rate of 17/min, and temperature of 37.3C (98.7F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of waldenstr\u00f6m macroglobulinemia with symptomatic hyperviscosity. Which of the following is the most appropriate next step in clinical management according to Australian Therapeutic Guidelines (eTG) and national consensus guidelines?",
    "options": [
      {
        "text": "High-flow oxygen therapy via non-rebreather mask in acute hypercapnic respiratory failure",
        "correct": false,
        "explanation": "Incorrect: Uncontrolled high FiO2 in hypercapnic chronic lung disease abolishes hypoxic respiratory drive, precipitating carbon dioxide narcosis."
      },
      {
        "text": "Immediate blood transfusion for asymptomatic normovolemic moderate anemia",
        "correct": false,
        "explanation": "Incorrect: Transfusion in stable chronic anemia without active ischemia exposes the patient to unnecessary alloimmunization and volume overload."
      },
      {
        "text": "Immediate exploratory surgical intervention without prior hemodynamic stabilization",
        "correct": false,
        "explanation": "Incorrect: Emergency surgery without preliminary physiological optimization and volume resuscitation significantly increases perioperative mortality."
      },
      {
        "text": "Routine abdominal computed tomography with intravenous contrast",
        "correct": false,
        "explanation": "Incorrect: Immediate cross-sectional contrast imaging without baseline renal function assessment or targeted hemodynamic evaluation is inappropriate."
      },
      {
        "text": "Emergency therapeutic plasmapheresis followed by clone-directed chemoimmunotherapy",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is emergency therapeutic plasmapheresis followed by clone-directed chemoimmunotherapy. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Waldenstr\u00f6m Macroglobulinemia with Symptomatic Hyperviscosity.\\n\\nClinical Discussion: This clinical presentation corresponds to Waldenstr\u00f6m Macroglobulinemia with Symptomatic Hyperviscosity. The cornerstone of management involves emergency therapeutic plasmapheresis followed by clone-directed chemoimmunotherapy. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Waldenstr\u00f6m Macroglobulinemia with Symptomatic Hyperviscosity.",
